 $st=mysqli_prepare($conn,"SELECT * FROM results WHERE student_id=? AND year=? AND semester=? AND approval_status='approved' AND publish_status='published' ORDER BY subject_code");
 mysqli_stmt_bind_param($st,'sss',$row['student_id'],$row['academic_year'],$row['semester']);mysqli_stmt_execute($st);$rs=mysqli_stmt_get_result($st);$current=[];while($x=mysqli_fetch_assoc($rs))$current[]=$x;
